void sortArray(int arr[], int size) 
{
    quickSort(arr, 0, size - 1); 
} 

// Driver program to test above functions
int main(void) 
{
    int arr[] = { 12, 11, 13, 5, 6, 7 };
    int n = sizeof(arr)/sizeof(arr[0]);
    printf("Unsorted array:\n");
    for (int i = 0; i < n; i++)
        printf("%d ", arr[i]);
    sortArray(arr, n);
    printf("\nSorted array:\n");
    for (int i = 0; i < n; i++)
        printf("%d ", arr[i]);
    return 0;
} 

